import sys

def max_possible_value(E, P, M):
    def evaluate(expr):
        stack = []
        num = 0
        sign = 1
        for char in expr:
            if char.isdigit():
                num = num * 10 + int(char)
            elif char == '+':
                stack.append(sign * num)
                num = 0
                sign = 1
            elif char == '-':
                stack.append(sign * num)
                num = 0
               sign = -1
            elif char == '(':
                stack.append(sign)
                stack.append('(')
                sign = 1
                num = 0
            elif char == ')':
                stack.append(sign * num)
                num = 0
                total = 0
                while stack[-1] != '(':
                    total += stack.pop()
                stack.pop()
                sign = stack.pop()
                stack.append(sign * total)
        stack.append(sign * num)
        return sum(stack)

    def backtrack(expr, P, M):
        if P == 0 and M == 0:
            return evaluate(expr)
        max_val = float('-inf')
        for i, char in enumerate(expr):
            if char == '?':
                max_val = max(max_val, backtrack(expr[:i] + '+' + expr[i+1:], P-1, M), backtrack(expr[:i] + '-' + expr[i+1:], P, M-1))
        return max_val

    return backtrack(E, P, M)

input = sys.stdin.read().split()
E = input[0]
P, M = map(int, input[1:])
print(max_possible_value(E, P, M))
